import XCTest
@testable import ColorComposerCore

/// Solver parity against the committed golden-vector corpus.
///
/// The corpus is a byte-identical copy of `priv/parity/v1/corpus.json` from
/// the `color_matching` server (viamin/color_matching#111, merged as #112),
/// generated by `mix parity.generate` and guarded byte-for-byte by the
/// server's CI. Replaying it here pins `WeightedSquaredErrorScorer` — and the
/// solver's earliest-wins selection — to the Elixir `WeightedSquaredError` /
/// `IlluminantMatching.best_match/4` behavior, so the two implementations
/// cannot silently diverge on tie-breaking, missing-measurement exclusion, or
/// channel weighting.
///
/// When the corpus `algorithm_version` changes, every expectation has moved
/// upstream and this suite must be re-verified against the new corpus in the
/// same change that updates the fixture.
///
/// See `docs/solver-parity-corpus.md` for how to refresh the fixture.
final class SolverParityCorpusTests: XCTestCase {
    /// Corpus scores are dyadic rationals (channel values are multiples of
    /// 1/16, weights at most 1.5), exactly representable as `Double`s, so a
    /// 1e-12 tolerance is effectively bit-exact while staying robust to a
    /// future corpus that uses non-dyadic values.
    private static let parityTolerance = 1e-12

    private let corpus: ParityCorpus = {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures", isDirectory: true)
            .appendingPathComponent("parity-v1-corpus.json")

        guard let data = try? Data(contentsOf: url) else {
            fatalError("Missing parity corpus fixture at \(url.path). See docs/solver-parity-corpus.md.")
        }
        do {
            return try JSONDecoder().decode(ParityCorpus.self, from: data)
        } catch {
            fatalError("Undecodable parity corpus fixture at \(url.path): \(error)")
        }
    }()

    // MARK: - Corpus contract

    /// The corpus must declare the contract this suite verifies: the scorer
    /// this app mirrors, the earliest-index-wins selection policy, the
    /// missing-measurement policy, and exactly the canonical light sources.
    func testCorpusMetadataMatchesSwiftSolverContract() {
        XCTAssertEqual(corpus.algorithmVersion, 1,
                       "The corpus algorithm_version changed; every expectation has moved — re-verify parity against the new corpus before updating this assertion.")
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(Set(corpus.lightSources), Set(LightingCondition.allCases.map(\.rawValue)))
    }

    /// A corpus refresh must keep covering the cases that historically
    /// diverged between client and server: exact ties (earliest-wins), the
    /// excluded-never-zero missing-measurement policy, and scenarios where no
    /// candidate is selectable. Dropping any of these from the corpus would
    /// silently weaken parity enforcement.
    func testCorpusKeepsTieExclusionAndNoSelectionCoverage() {
        XCTAssertGreaterThanOrEqual(corpus.scenarios.count, 12)

        let tieScenarios = corpus.scenarios.filter { $0.expected.tieBroke == true }
        XCTAssertGreaterThanOrEqual(tieScenarios.count, 5, "Corpus must keep exact-tie scenarios.")

        let scenariosWithExclusions = corpus.scenarios.filter { scenario in
            scenario.expected.scores.contains { $0.score == .excluded }
        }
        XCTAssertGreaterThanOrEqual(scenariosWithExclusions.count, 4,
                                    "Corpus must keep missing-measurement exclusion scenarios.")

        let noSelectionScenarios = corpus.scenarios.filter { $0.expected.selectedIndex == nil }
        XCTAssertGreaterThanOrEqual(noSelectionScenarios.count, 2,
                                    "Corpus must keep scenarios where no candidate is selectable.")
    }

    // MARK: - Scorer parity

    /// Every per-candidate score in the corpus's score table must match the
    /// Swift scorer exactly: numeric scores agree within `parityTolerance`,
    /// and `"excluded"` entries come back as `.excluded`.
    func testScorerScoreTableMatchesElixirGoldenVectors() throws {
        for scenario in corpus.scenarios {
            let outcome = try replay(scenario)

            XCTAssertEqual(outcome.results.count, scenario.expected.scores.count,
                           "\(scenario.id): score table length")

            for entry in scenario.expected.scores {
                switch (outcome.results[entry.index], entry.score) {
                case (.excluded, .excluded):
                    continue
                case let (.score(value), .score(expected)):
                    XCTAssertEqual(value, expected, accuracy: Self.parityTolerance,
                                   "\(scenario.id): candidate \(entry.index) score")
                case (.score(let value), .excluded):
                    XCTFail("\(scenario.id): candidate \(entry.index) expected \"excluded\" but scored \(value)")
                case (.excluded, .score(let expected)):
                    XCTFail("\(scenario.id): candidate \(entry.index) expected score \(expected) but was excluded")
                }
            }
        }
    }

    /// Selection must match the corpus exactly: the earliest index attaining
    /// the minimum score wins (`tie_broke`/`tied_indices` evidence included),
    /// the recorded error matches, and the selected color keeps its recorded
    /// hex. Scenarios where every candidate is excluded must select nothing.
    func testSelectionTieBreakErrorAndHexMatchCorpus() throws {
        for scenario in corpus.scenarios {
            let outcome = try replay(scenario)
            let expected = scenario.expected

            XCTAssertEqual(outcome.selectedIndex, expected.selectedIndex, "\(scenario.id): selected index")

            if let selected = outcome.selectedIndex {
                let expectedHex = try XCTUnwrap(expected.selectedHexColor, "\(scenario.id)")
                XCTAssertEqual(outcome.palette[selected].hex, expectedHex,
                               "\(scenario.id): selected color hex")
                XCTAssertEqual(outcome.bestScore ?? 0, try XCTUnwrap(expected.error),
                               accuracy: Self.parityTolerance, "\(scenario.id): selected error")
            } else {
                XCTAssertNil(expected.error, "\(scenario.id): error must be null without a selection")
                XCTAssertNil(expected.selectedHexColor, "\(scenario.id): hex must be null without a selection")
            }

            XCTAssertEqual(outcome.tiedIndices, expected.tiedIndices, "\(scenario.id): tied indices")
            XCTAssertEqual(outcome.tieBroke, expected.tieBroke, "\(scenario.id): tie_broke")
        }
    }

    /// The solver's optimized contiguous fast path (and its earliest-wins
    /// tie-breaking) must agree with the corpus wherever the corpus target is
    /// expressible as source grids — i.e. whenever the target carries every
    /// active channel. The single scenario whose *target* is missing an
    /// active channel cannot be represented as grids (grids always provide
    /// every active channel) and is covered by the scorer-level tests above.
    func testSolverFastPathAgreesWithCorpusSelection() throws {
        var replayed = 0

        for scenario in corpus.scenarios {
            let outcome = try replay(scenario)
            let active = outcome.weights.activeConditions
            guard active.allSatisfy({ outcome.target.value(for: $0) != nil }) else { continue }

            let sourceGrids: [LightingCondition: BrightnessGrid] = Dictionary(
                uniqueKeysWithValues: active.map { condition in
                    (condition, BrightnessGrid(width: 1, height: 1, fill: outcome.target.value(for: condition)!))
                }
            )

            let result = try CompositionSolver().solve(
                palette: outcome.palette,
                sourceGrids: sourceGrids,
                weights: outcome.weights
            )
            replayed += 1

            XCTAssertEqual(result.colorIndex(x: 0, y: 0), scenario.expected.selectedIndex,
                           "\(scenario.id): solver selection")

            if let selected = scenario.expected.selectedIndex {
                XCTAssertEqual(result.error(x: 0, y: 0), try XCTUnwrap(scenario.expected.error),
                               accuracy: Self.parityTolerance, "\(scenario.id): solver error")
            } else {
                XCTAssertEqual(result.unmatchedCellCount, 1, "\(scenario.id): cell must be unmatched")
                XCTAssertEqual(result.error(x: 0, y: 0), .infinity, "\(scenario.id): error must be infinite")
            }

            let excludedCount = scenario.expected.scores.filter { $0.score == .excluded }.count
            XCTAssertEqual(result.excludedCandidateCount, excludedCount,
                           "\(scenario.id): excluded candidate count")
        }

        XCTAssertGreaterThanOrEqual(replayed, 11, "The solver replay must cover the corpus's replayable scenarios.")
    }

    // MARK: - Replay

    private struct ReplayOutcome {
        let palette: [PaletteColor]
        let target: TargetResponseVector
        let weights: ChannelWeights
        let results: [ScorerResult]
        let selectedIndex: Int?
        let bestScore: Double?
        let tiedIndices: [Int]

        var tieBroke: Bool? {
            bestScore == nil ? nil : tiedIndices.count > 1
        }
    }

    /// Replays one scenario exactly the way the upstream README prescribes:
    /// score every palette color against the scenario target using the
    /// scenario weights, then reduce with the solver's earliest-wins policy.
    private func replay(_ scenario: ParityScenario) throws -> ReplayOutcome {
        let weights = Self.channelWeights(from: scenario.weights)
        let target = Self.targetVector(from: scenario.target)
        let palette = try scenario.palette.enumerated().map { offset, entry in
            XCTAssertEqual(entry.index, offset, "\(scenario.id): palette entry index must match its position")
            return try Self.paletteColor(from: entry, index: offset)
        }

        let scorer = WeightedSquaredErrorScorer()
        let results = palette.map { scorer.score(candidate: $0, target: target, weights: weights) }

        var selectedIndex: Int?
        var bestScore: Double?
        for (index, result) in results.enumerated() {
            guard case .score(let value) = result else { continue }
            if bestScore == nil || value < bestScore! {
                bestScore = value
                selectedIndex = index
            }
        }

        let tiedIndices: [Int] = bestScore.map { best in
            results.indices.filter { index in
                guard case .score(let value) = results[index] else { return false }
                return abs(value - best) <= Self.parityTolerance
            }
        } ?? []

        return ReplayOutcome(
            palette: palette,
            target: target,
            weights: weights,
            results: results,
            selectedIndex: selectedIndex,
            bestScore: bestScore,
            tiedIndices: tiedIndices
        )
    }

    /// Corpus weights may carry unknown light sources (e.g. `ultraviolet` in
    /// the `unknown-weight-ignored` scenario) that no canonical channel can
    /// measure; they are dropped, matching the scorer's canonical-channel
    /// universe.
    private static func channelWeights(from raw: [String: Double]) -> ChannelWeights {
        func weight(_ condition: LightingCondition) -> Double {
            raw[condition.rawValue] ?? 0
        }
        return ChannelWeights(
            white: weight(.white),
            red: weight(.red),
            green: weight(.green),
            blue: weight(.blue),
            lps: weight(.lps)
        )
    }

    private static func targetVector(from vector: ParityVector) -> TargetResponseVector {
        var brightness: [LightingCondition: Double] = [:]
        for (key, value) in vector.channels {
            if let condition = LightingCondition(rawValue: key) {
                brightness[condition] = value
            }
        }
        return TargetResponseVector(brightness)
    }

    private static func paletteColor(from vector: ParityVector, index: Int) throws -> PaletteColor {
        let rgb = try XCTUnwrap(RGBColor(hex: vector.hexColor),
                                "Corpus hex \(vector.hexColor) must parse")
        var responses: [LightingCondition: IlluminationResponse] = [:]
        for (key, value) in vector.channels {
            if let condition = LightingCondition(rawValue: key) {
                responses[condition] = IlluminationResponse(brightness: value)
            }
        }
        return PaletteColor(id: index, hex: vector.hexColor, rgb: rgb, responses: responses)
    }
}

// MARK: - Corpus wire format (priv/parity/v1/corpus.json)

/// Top level of the parity corpus. Keys are explicit (not snake-case
/// converted) because the corpus is an external artifact whose field names
/// are part of the cross-repo contract.
private struct ParityCorpus: Decodable {
    let algorithmVersion: Int
    let lightSources: [String]
    let missingPolicy: String
    let scorer: String
    let selection: String
    let scenarios: [ParityScenario]

    enum CodingKeys: String, CodingKey {
        case algorithmVersion = "algorithm_version"
        case lightSources = "light_sources"
        case missingPolicy = "missing_policy"
        case scorer
        case selection
        case scenarios
    }
}

private struct ParityScenario: Decodable {
    let id: String
    let description: String
    let weights: [String: Double]
    let palette: [ParityVector]
    let target: ParityVector
    let expected: ParityExpectation
}

private struct ParityVector: Decodable {
    let index: Int?
    let hexColor: String
    let channels: [String: Double]

    enum CodingKeys: String, CodingKey {
        case index
        case hexColor = "hex_color"
        case channels
    }
}

private struct ParityExpectation: Decodable {
    let error: Double?
    let scores: [ParityScoreEntry]
    let selectedIndex: Int?
    let selectedHexColor: String?
    let tieBroke: Bool?
    let tiedIndices: [Int]

    enum CodingKeys: String, CodingKey {
        case error
        case scores
        case selectedIndex = "selected_index"
        case selectedHexColor = "selected_hex_color"
        case tieBroke = "tie_broke"
        case tiedIndices = "tied_indices"
    }
}

private struct ParityScoreEntry: Decodable {
    let index: Int
    let score: ParityScore
}

/// One expected score: a number, or the literal string `"excluded"`.
private enum ParityScore: Decodable, Equatable {
    case score(Double)
    case excluded

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let value = try? container.decode(Double.self) {
            self = .score(value)
        } else if let raw = try? container.decode(String.self) {
            guard raw == "excluded" else {
                throw DecodingError.dataCorruptedError(
                    in: container,
                    debugDescription: "Unexpected score value \"\(raw)\""
                )
            }
            self = .excluded
        } else {
            throw DecodingError.dataCorruptedError(
                in: container,
                debugDescription: "Score must be a number or \"excluded\""
            )
        }
    }
}
